 auto draw=[&](){target.clear(sf::Color::Transparent);child->DrawSprites(&target,sf::RenderStates::Default);target.display();auto image=target.getTexture().copyToImage();double x=0,y=0,n=0;for(unsigned b=0;b<128;++b)for(unsigned a=0;a<128;++a){auto c=image.getPixel(a,b);if(c.a&&c.r>200){x+=(a+.5)*c.a;y+=(b+.5)*c.a;n+=c.a;}}if(!n)throw std::runtime_error("Locked accessory vanished");return sf::Vector2f(float(x/n),float(y/n));};
