 {AppConfig app;UIConfig ui;app._appLocation=fs::absolute("RahiTuber").string()+"/";LayerManager manager;manager.Init(&app,&ui);if(!manager.LoadLayers((dir/"avatar.xml").string()))throw std::runtime_error("Rig project load failed");auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(10);while(manager.IsLoading()&&std::chrono::steady_clock::now()<deadline)sf::sleep(sf::milliseconds(10));if(manager.IsLoading()||manager.GetLayers().empty())throw std::runtime_error("Rig project load timed out");sf::RenderTexture finish;if(!finish.create(32,32))throw std::runtime_error("Load check target failed");manager.Draw(&finish,32,32,0,1,PH_NONE);auto& l=manager.GetLayers().front();if(!l._attachmentBound||std::abs(l._attachmentParentBase.transformPoint(0,0).x-17)>.001f||!l._rigEnabled||l._rigBones.size()!=3||std::fabs(l._rigBones[1].radius-.32f)>.001f||!l._liveFaceEnabled[2]||std::fabs(l._liveFacePosition[2].y-.42f)>.001f||l._rigAttachLayer!="test-body"||std::abs(l._liveFaceSettings[2].zoom-3.25f)>.001f||std::abs(l._liveFaceSettings[2].brightness-.6f)>.001f||l._liveFaceSettings[2].mask!=3||std::abs(l._liveFaceSettings[2].precisionPadding-.7f)>.001f||std::abs(l._liveFaceSettings[2].precisionFeather-.5f)>.001f||std::abs(l._liveFaceSettings[2].precisionScaleY-.9f)>.001f||std::abs(l._plushFlatness-.7f)>.001f)throw std::runtime_error("Rig or live facial settings did not round trip");}
